function r(n){try{return window.open(n,"_blank","noopener,noreferrer")}catch{return null}}async function o(n){if(!n)return!1;try{const e=await fetch("/api/settings/open-external",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:n})});if(e.ok){const t=await e.json().catch(()=>null);if(t!=null&&t.opened)return!0}}catch{}try{return r(n)!==null}catch{return!1}}export{o};
